package com.example.auth;

public class ApiKeyVerifier {
    private final String expected;

    public ApiKeyVerifier(String expected) {
        this.expected = expected;
    }

    /** True when the presented API key equals the configured key. */
    public boolean matches(String presented) {
        return presented != null && expected.equals(presented);
    }
}

package com.example.auth;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class ApiKeyVerifierTest {
    @Test
    void acceptsConfiguredKey() {
        ApiKeyVerifier verifier = new ApiKeyVerifier("k-123");
        assertTrue(verifier.matches("k-123"));
        assertFalse(verifier.matches("k-124"));
    }
}
